INSERT INTO dump_descriptions (base_key, description) VALUES ('nouplinkbuildingsound', 'Mutes Uplink and Fuel Cell opening/building sounds.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('enemycullnolpe', 'Shortens render distance for several enemies and a Spider spawner, including Grunts, Swarmers, and Mactera.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('flamethroweroverhaul', 'Rebalances Flamethrower: direct damage 11→12, explosive-target radial damage 55→27.5, projectile hold time 0.4→0.833s, and sticky flames last 5s.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
